END;
"}

{"proname":"SeparationCase_preserve_employee_notice","arguments":"","result":"trigger","lanname":"plpgsql","prosrc":"
DECLARE employee_state "EmployeeStatus";
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW."submissionSource"='ESS' THEN
   SELECT "employeeStatus" INTO employee_state FROM "Employee" WHERE "id"=NEW."employeeId" AND "organizationId"=NEW."organizationId" FOR UPDATE;
   IF employee_state IS DISTINCT FROM 'ACTIVE' OR NOT EXISTS (
    SELECT 1 FROM "EmployeeAccount" a JOIN "User" u ON u."id"=a."userId"
    WHERE a."employeeId"=NEW."employeeId" AND a."organizationId"=NEW."organizationId" AND a."status"='ACTIVE'
      AND u."id"=NEW."initiatedById" AND u."organizationId"=NEW."organizationId" AND u."role"='EMPLOYEE'
   ) THEN RAISE EXCEPTION 'Current active employee identity is required for an ESS notice'; END IF;
  END IF;
  RETURN NEW;
 END IF;
 IF NEW."submissionSource" IS DISTINCT FROM OLD."submissionSource" OR NEW."employeeNoticeSnapshot" IS DISTINCT FROM OLD."employeeNoticeSnapshot" THEN RAISE EXCEPTION 'Original employee notice provenance is immutable'; END IF;
 IF OLD."submissionSource"='ESS' AND ROW(NEW."separationType",NEW."reason",NEW."noticeDate",NEW."proposedLastWorkingDay",NEW."proposedEffectiveDate") IS DISTINCT FROM ROW(OLD."separationType",OLD."reason",OLD."noticeDate",OLD."proposedLastWorkingDay",OLD."proposedEffectiveDate") THEN RAISE EXCEPTION 'Employee submitted reason and dates cannot be rewritten'; END IF;
 IF OLD."acknowledgedAt" IS NOT NULL AND ROW(NEW."acknowledgedById",NEW."acknowledgedAt",NEW."acknowledgmentRemarks") IS DISTINCT FROM ROW(OLD."acknowledgedById",OLD."acknowledgedAt",OLD."acknowledgmentRemarks") THEN RAISE EXCEPTION 'Recorded receipt acknowledgment is immutable'; END IF;
 RETURN NEW;
END;
"}

{"proname":"h4_assert_account_consistency","arguments":"","result":"trigger","lanname":"plpgsql","prosrc":"
DECLARE
  related_org TEXT;
  linked_role "Role";
BEGIN
  SELECT "organizationId", "role" INTO related_org, linked_role FROM "User" WHERE "id" = NEW."userId";
  IF related_org IS DISTINCT FROM NEW."organizationId" OR linked_role IS DISTINCT FROM 'EMPLOYEE' THEN
    RAISE EXCEPTION 'Invalid employee account user or tenant';
  END IF;
  SELECT "organizationId" INTO related_org FROM "Employee" WHERE "id" = NEW."employeeId";
  IF related_org IS DISTINCT FROM NEW."organizationId" THEN RAISE EXCEPTION 'Cross-tenant employee account link'; END IF;
  SELECT "organizationId" INTO related_org FROM "User" WHERE "id" = NEW."createdById" AND "role" IN ('ORGANIZATION_ADMIN', 'HR_ADMIN');
  IF related_org IS DISTINCT FROM NEW."organizationId" THEN RAISE EXCEPTION 'Invalid employee account creator'; END IF;
  IF TG_OP = 'UPDATE' AND (NEW."organizationId", NEW."userId", NEW."employeeId") IS DISTINCT FROM (OLD."organizationId", OLD."userId", OLD."employeeId") THEN
    RAISE EXCEPTION 'Employee account ownership is immutable';
  END IF;
  RETURN NEW;
END;
"}

{"proname":"h4_assert_audit_consistency","arguments":"","result":"trigger","lanname":"plpgsql","prosrc":"
DECLARE
  related_org TEXT;
BEGIN
  SELECT "organizationId" INTO related_org FROM "User" WHERE "id" = NEW."actorUserId";
  IF related_org IS DISTINCT FROM NEW."organizationId" THEN RAISE EXCEPTION 'Cross-tenant employee account audit actor'; END IF;
  IF NEW."employeeAccountId" IS NOT NULL THEN
    SELECT "organizationId" INTO related_org FROM "EmployeeAccount" WHERE "id" = NEW."employeeAccountId";
    IF related_org IS DISTINCT FROM NEW."organizationId" THEN RAISE EXCEPTION 'Cross-tenant employee account audit'; END IF;
  END IF;
  RETURN NEW;
END;
"}

